package vn.studylock;
import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.net.Uri;
import android.os.Bundle;
import android.provider.Settings;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import java.util.*;
public class MainActivity extends Activity {
    private Store store; private LinearLayout root; private boolean authorized=false;
    @Override public void onCreate(Bundle state){super.onCreate(state);store=new Store(this);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);}
    @Override public void onResume(){super.onResume();if(!authorized)gate();}
    @Override public void onStop(){super.onStop();authorized=false;}
    private void page(){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(Ui.BG);root=Ui.column(this);scroll.addView(root,new ScrollView.LayoutParams(-1,-2));setContentView(scroll);
        if(android.os.Build.VERSION.SDK_INT>=35)scroll.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets i=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(i.left,i.top,i.right,i.bottom);return insets;});}
    private void t(String s,int size,boolean bold){root.addView(Ui.text(this,s,size,bold?Ui.INK:Ui.MUTED,bold));}
    private void button(String s,boolean primary,Runnable action){Button b=Ui.button(this,s,primary);b.setOnClickListener(v->action.run());root.addView(b);}
    private EditText pinField(String hint){EditText e=new EditText(this);e.setHint(hint);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);e.setSingleLine(true);e.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(12)});root.addView(e);return e;}
    private void gate(){page();t("STUDYLOCK",14,true);t("Khu vực phụ huynh",28,true);boolean create=!store.hasPin();t(create?"Tạo mã PIN riêng từ 6–12 chữ số. Không chia sẻ với trẻ.":"Nhập mã PIN để xem và thay đổi cài đặt.",16,false);
        EditText a=pinField(create?"Tạo mã PIN":"Mã PIN");EditText b=create?pinField("Nhập lại mã PIN"):null;TextView msg=Ui.text(this,"",14,Ui.RED,false);root.addView(msg);
        button(create?"Tạo và tiếp tục":"Mở cài đặt",true,()->{String pin=a.getText().toString();if(create){if(!pin.matches("[0-9]{6,12}")||!pin.equals(b.getText().toString())){msg.setText("PIN cần 6–12 chữ số và hai lần nhập giống nhau.");return;}if(!store.setPin(pin)){msg.setText("Không thể tạo PIN trên thiết bị này.");return;}}else{if(store.waitSeconds()>0){msg.setText("Thử lại sau "+store.waitSeconds()+" giây.");return;}if(!store.verify(pin)){msg.setText(store.waitSeconds()>0?"Nhập sai nhiều lần. Chờ 30 giây.":"Mã PIN không đúng.");a.setText("");return;}}authorized=true;((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(a.getWindowToken(),0);settings();});
        t("StudyLock không đọc nội dung màn hình và không gửi dữ liệu lên mạng. Nếu quên PIN, cần đặt lại dữ liệu ứng dụng; việc này cũng xóa lịch và cấu hình.",14,false);
    }
    private Spinner spin(String[] names,int selected){Spinner s=new Spinner(this);ArrayAdapter<String> a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names);s.setAdapter(a);s.setSelection(selected);s.setMinimumHeight(Ui.dp(this,48));root.addView(s);return s;}
    private boolean serviceOn(){String s=Settings.Secure.getString(getContentResolver(),Settings.Secure.ENABLED_ACCESSIBILITY_SERVICES);if(s==null)return false;ComponentName own=new ComponentName(this,LockService.class);for(String x:s.split(":")){if(own.equals(ComponentName.unflattenFromString(x)))return true;}return false;}
    private Map<String,String> apps(){Map<String,String> out=new LinkedHashMap<>(Store.DEFAULTS);PackageManager pm=getPackageManager();Intent launcher=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER);List<ResolveInfo> list=pm.queryIntentActivities(launcher,0);list.sort(Comparator.comparing(x->x.loadLabel(pm).toString(),String.CASE_INSENSITIVE_ORDER));for(ResolveInfo r:list){String pkg=r.activityInfo.packageName;if(!store.safePackage(pkg))out.put(pkg,r.loadLabel(pm).toString());}return out;}
    private void settings(){page();t("STUDYLOCK  /  PHỤ HUYNH",13,true);t("Lịch học và giải trí",27,true);t(serviceOn()?"Dịch vụ khóa đang được cấp quyền.":"Dịch vụ khóa chưa được bật. Lưu cấu hình rồi cấp quyền.",15,false);
        t("Hồ sơ học tập đang dùng: "+store.profileName(store.profile()),16,true);button("Chọn / thêm / đổi tên hồ sơ",false,()->profiles());t("Lịch, hạn mức và thời gian giải trí dùng chung trên điện thoại; kết quả học tập riêng từng trẻ.",14,false);
        Switch enabled=new Switch(this);enabled.setText("Bật khóa ứng dụng");enabled.setChecked(store.enabled());root.addView(enabled);Ui.space(root,12);
        t("01  •  Hạn mức và lịch giải trí",19,true);
        final String[] dayNames={"Thứ Hai","Thứ Ba","Thứ Tư","Thứ Năm","Thứ Sáu","Thứ Bảy","Chủ nhật"};
        final int[] active={java.time.LocalDate.now().getDayOfWeek().getValue()-1};
        final String[] limitDraft=new String[7]; final List<List<int[]>> weeks=new ArrayList<>();
        for(int d=0;d<7;d++){limitDraft[d]=String.valueOf(store.limit(d));weeks.add(new ArrayList<>(Rules.parse(store.schedule(d))));}
        TextView usage=Ui.text(this,"",15,Ui.TEAL,true);root.addView(usage);
        Runnable updateUsage=()->{long used=store.usedToday()/1000,left=(store.dailyRemaining()+999)/1000;usage.setText("Hôm nay: đã dùng "+(used/60)+" phút "+(used%60)+" giây / "+store.limit()+" phút\nCòn lại: "+(left/60)+" phút "+(left%60)+" giây");};updateUsage.run();
        button("Cập nhật thời gian đã dùng",false,updateUsage);
        t("Chọn ngày để thiết lập lịch và hạn mức riêng. Cho phép 0 phút để khóa cả ngày.",14,false);
        Spinner day=spin(dayNames,active[0]);
        t("Hạn mức ngày đang chọn (phút)",14,false);
        EditText limit=new EditText(this);limit.setInputType(InputType.TYPE_CLASS_NUMBER);limit.setSingleLine(true);limit.setText(limitDraft[active[0]]);root.addView(limit);
        t("Khung giờ tự do; để trống nếu luôn yêu cầu làm bài. Khung qua nửa đêm thuộc ngày bắt đầu; ngày mới áp dụng hạn mức mới.",14,false);
        LinearLayout scheduleRows=new LinearLayout(this);scheduleRows.setOrientation(LinearLayout.VERTICAL);root.addView(scheduleRows);
        renderWindows(scheduleRows,weeks.get(active[0]));
        day.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){} public void onItemSelected(AdapterView<?> p,View v,int position,long id){limitDraft[active[0]]=limit.getText().toString();active[0]=position;limit.setText(limitDraft[position]);renderWindows(scheduleRows,weeks.get(position));}});
        button("+ Thêm khung giờ",false,()->editWindow(scheduleRows,weeks.get(active[0]),-1));
        button("Sao chép ngày này sang tất cả ngày",false,()->new AlertDialog.Builder(this).setMessage("Ghi đè lịch và hạn mức của 6 ngày còn lại bằng ngày đang chọn?").setNegativeButton("Hủy",null).setPositiveButton("Sao chép",(d,w)->{limitDraft[active[0]]=limit.getText().toString();String sc=Rules.format(weeks.get(active[0]));for(int i=0;i<7;i++)if(i!=active[0]){limitDraft[i]=limitDraft[active[0]];weeks.set(i,new ArrayList<>(Rules.parse(sc)));}Toast.makeText(this,"Đã sao chép bản nháp. Bấm Lưu cấu hình.",Toast.LENGTH_SHORT).show();}).show());
        Switch warning=new Switch(this);warning.setText("Cảnh báo khi còn 1 phút");warning.setChecked(store.warning());root.addView(warning);
        t("02  •  Bài tập",19,true);t("Khối lớp",14,false);Spinner grade=spin(new String[]{"Lớp 4","Lớp 5","Lớp 6"},store.grade()-4);t("Môn học",14,false);String mode=store.mode();Spinner subject=spin(new String[]{"Ngẫu nhiên Toán / Tiếng Anh","Chỉ Toán","Chỉ Tiếng Anh"},mode.equals("math")?1:mode.equals("english")?2:0);t("Mức thưởng chọn sẵn khi mở màn hình bài tập",14,false);Spinner reward=spin(new String[]{"5 phút","10 phút","20 phút"},store.reward()==5?0:store.reward()==20?2:1);
        t("Học kỳ (phân nhóm ôn tập tham khảo)",14,false);Spinner term=spin(new String[]{"Cả năm","Học kỳ I","Học kỳ II"},store.term());
        t("Độ khó ban đầu",14,false);Spinner difficulty=spin(new String[]{"Cơ bản","Trung bình","Nâng cao"},store.difficulty()-1);Switch adaptive=new Switch(this);adaptive.setText("Tự điều chỉnh độ khó theo từng môn");adaptive.setChecked(store.adaptive());root.addView(adaptive);
        Spinner[] tiers=new Spinner[3];int[] minutes={5,10,20};for(int i=0;i<3;i++){t("Số câu đúng liên tiếp cho "+minutes[i]+" phút",14,false);tiers[i]=spin(new String[]{"1 câu","2 câu","3 câu","4 câu","5 câu","6 câu","7 câu","8 câu","9 câu","10 câu"},store.tierCount(minutes[i])-1);}
        t("Nghỉ bắt buộc sau khi hết thời gian thưởng (ngoài lịch)",14,false);Spinner rest=spin(new String[]{"Không nghỉ","1 phút","3 phút","5 phút","10 phút","15 phút"},Math.max(0,Arrays.asList(0,1,3,5,10,15).indexOf(store.restMinutes())));
        Switch typed=new Switch(this);typed.setText("Toán: tự nhập kết quả (không trắc nghiệm)");typed.setChecked(store.typedMath());root.addView(typed);
        t("03  •  Ứng dụng cần khóa",19,true);Set<String> selected=store.packages();Map<String,String> all=apps();for(String p:selected)all.putIfAbsent(p,p);TextView summary=Ui.text(this,"Đã chọn "+selected.size()+" ứng dụng / gói",15,Ui.MUTED,false);root.addView(summary);
        button("Chọn ứng dụng",false,()->{String[] ids=all.keySet().toArray(new String[0]);String[] labels=new String[ids.length];boolean[] checked=new boolean[ids.length];for(int i=0;i<ids.length;i++){labels[i]=all.get(ids[i])+"\n"+ids[i];checked[i]=selected.contains(ids[i]);}new AlertDialog.Builder(this).setTitle("Ứng dụng cần khóa").setMultiChoiceItems(labels,checked,(dialog,which,value)->checked[which]=value).setNegativeButton("Hủy",null).setPositiveButton("Xác nhận",(dialog,which)->{selected.clear();for(int i=0;i<ids.length;i++)if(checked[i])selected.add(ids[i]);summary.setText("Đã chọn "+selected.size()+" ứng dụng / gói");}).show();});
        button("Thêm các trình duyệt đã phát hiện",false,()->{Intent intent=new Intent(Intent.ACTION_VIEW,Uri.parse("https://example.org")).addCategory(Intent.CATEGORY_BROWSABLE);for(ResolveInfo r:getPackageManager().queryIntentActivities(intent,PackageManager.MATCH_ALL)){String pkg=r.activityInfo.packageName;if(!store.safePackage(pkg)){selected.add(pkg);all.putIfAbsent(pkg,r.loadLabel(getPackageManager()).toString());}}summary.setText("Đã chọn "+selected.size()+" ứng dụng / gói");});
        TextView message=Ui.text(this,"",14,Ui.RED,false);root.addView(message);button("Lưu cấu hình",true,()->{limitDraft[active[0]]=limit.getText().toString();String[] schedules=new String[7];int[] limits=new int[7];for(int d=0;d<7;d++){try{limits[d]=Integer.parseInt(limitDraft[d]);if(limits[d]<0||limits[d]>1440)throw new NumberFormatException();schedules[d]=Rules.format(weeks.get(d));}catch(NumberFormatException e){message.setTextColor(Ui.RED);message.setText(dayNames[d]+": hạn mức phải từ 0 đến 1440 phút.");return;}}boolean reset=store.grade()!=grade.getSelectedItemPosition()+4||store.term()!=term.getSelectedItemPosition()||store.difficulty()!=difficulty.getSelectedItemPosition()+1||store.adaptive()!=adaptive.isChecked();store.saveLearning(term.getSelectedItemPosition(),difficulty.getSelectedItemPosition()+1,adaptive.isChecked(),new int[]{tiers[0].getSelectedItemPosition()+1,tiers[1].getSelectedItemPosition()+1,tiers[2].getSelectedItemPosition()+1},new int[]{0,1,3,5,10,15}[rest.getSelectedItemPosition()],reset);store.save(schedules,grade.getSelectedItemPosition()+4,new int[]{5,10,20}[reward.getSelectedItemPosition()],store.count(),new String[]{"mixed","math","english"}[subject.getSelectedItemPosition()],selected,enabled.isChecked(),limits,typed.isChecked(),warning.isChecked());updateUsage.run();message.setTextColor(Ui.TEAL);message.setText("Đã lưu. Thời gian thưởng cũ đã được hủy.");});
        Ui.space(root,12);t("04  •  Báo cáo học tập",19,true);button("Xem thống kê 7 ngày gần nhất",false,()->showReport(7));button("Xem thống kê 30 ngày gần nhất",false,()->showReport(30));button("Xuất CSV 7 ngày",false,()->exportReport(7));button("Xuất CSV 30 ngày",false,()->exportReport(30));
        Ui.space(root,12);t("05  •  Bảo mật và quyền",19,true);
        button("Bảo vệ gỡ ứng dụng (thiết bị được quản lý)",false,()->managedProtection());
        android.app.admin.DevicePolicyManager dpm=(android.app.admin.DevicePolicyManager)getSystemService(DEVICE_POLICY_SERVICE);
        if(dpm.isDeviceOwnerApp(getPackageName()))button("Thoát chế độ quản lý thiết bị",false,()->new AlertDialog.Builder(this).setTitle("Thu hồi quyền quản lý StudyLock?").setMessage("Bỏ bảo vệ gỡ cài đặt và thu hồi quyền Device Owner. Chỉ thực hiện bởi phụ huynh quản lý thiết bị.").setNegativeButton("Hủy",null).setPositiveButton("Thu hồi",(d,w)->{if(!authorized)return;try{dpm.setUninstallBlocked(new ComponentName(this,StudyAdmin.class),getPackageName(),false);dpm.clearDeviceOwnerApp(getPackageName());settings();}catch(RuntimeException e){Toast.makeText(this,"Hệ thống không cho phép thu hồi tại đây. Xem hướng dẫn README.",Toast.LENGTH_LONG).show();}}).show());
        button("Cấp quyền Trợ năng",false,()->new AlertDialog.Builder(this).setTitle("Quyền Trợ năng Android").setMessage("StudyLock chỉ nhận tên gói của cửa sổ ứng dụng và hiển thị màn hình bài tập. Không đọc nội dung màn hình hoặc gửi dữ liệu. Bạn có thể tắt quyền này trong Cài đặt Android. Hãy lưu cấu hình trước khi tiếp tục.").setNegativeButton("Hủy",null).setPositiveButton("Đồng ý, mở Cài đặt",(d,w)->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS))).show());
        button("Đổi mã PIN",false,()->changePin());button("Hủy thời gian thưởng hiện tại",false,()->{store.clearBonus();Toast.makeText(this,"Đã hủy thời gian thưởng",Toast.LENGTH_SHORT).show();});button("Khóa lại khu vực phụ huynh",false,()->{authorized=false;gate();});
        t("Giới hạn: trên điện thoại thông thường, dịch vụ Trợ năng không chống được gỡ ứng dụng, tắt quyền hoặc đổi giờ hệ thống. Không khóa cuộc gọi khẩn cấp hay phần Cài đặt hệ thống. Phụ huynh cần quản lý thiết bị trực tiếp.",14,false);
    }
    private void showReport(int days){StringBuilder b=new StringBuilder();for(int i=0;i<days;i++){java.time.LocalDate d=java.time.LocalDate.now().minusDays(i);long sec=store.used(d)/1000;b.append(d.format(java.time.format.DateTimeFormatter.ofPattern("dd/MM/yyyy"))).append(" – giải trí ").append(sec/60).append("p ").append(sec%60).append("s\n");for(String subject:new String[]{"math","english"}){int r=store.answers(d,subject,true),w=store.answers(d,subject,false);b.append(subject.equals("math")?"Toán: ":"Tiếng Anh: ").append(r).append(" đúng, ").append(w).append(" sai");if(r+w>0)b.append(" (đúng ").append(Math.round(100.0*r/(r+w))).append("%)");b.append("\n");}b.append("\n");}new AlertDialog.Builder(this).setTitle(store.profileName(store.profile())+" – "+days+" ngày (giải trí chung)").setMessage(b.toString()).setPositiveButton("Đóng",null).show();}
    private void profiles(){String[] names=new String[store.profileCount()];for(int i=0;i<names.length;i++)names[i]=store.profileName(i);new AlertDialog.Builder(this).setTitle("Chọn hồ sơ (bản nháp chưa lưu sẽ mất)").setItems(names,(d,i)->{if(authorized){store.selectProfile(i);settings();}}).setNeutralButton("Đổi tên",(d,w)->profileName(false)).setPositiveButton("Thêm trẻ",(d,w)->profileName(true)).setNegativeButton("Hủy",null).show();}
    private void profileName(boolean add){if(add&&store.profileCount()>=8){Toast.makeText(this,"Tối đa 8 hồ sơ",Toast.LENGTH_SHORT).show();return;}EditText input=new EditText(this);input.setSingleLine(true);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(40)});if(!add)input.setText(store.profileName(store.profile()));new AlertDialog.Builder(this).setTitle(add?"Thêm hồ sơ":"Đổi tên hồ sơ").setView(input).setNegativeButton("Hủy",null).setPositiveButton("Lưu",(d,w)->{if(!authorized)return;String name=input.getText().toString().trim();if(name.isEmpty())return;if(add)store.addProfile(name);else store.renameProfile(name);settings();}).show();}
    private String pendingCsv;
    private void exportReport(int days){StringBuilder b=new StringBuilder("\uFEFFNgày,Giải trí thiết bị (giây),Toán đúng,Toán sai,Tiếng Anh đúng,Tiếng Anh sai\n");for(int i=days-1;i>=0;i--){java.time.LocalDate d=java.time.LocalDate.now().minusDays(i);b.append(d).append(',').append(store.used(d)/1000);for(String sub:new String[]{"math","english"})for(boolean right:new boolean[]{true,false})b.append(',').append(store.answers(d,sub,right));b.append('\n');}pendingCsv=b.toString();Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("text/csv").putExtra(Intent.EXTRA_TITLE,"StudyLock-hoso"+(store.profile()+1)+"-"+days+"ngay.csv");try{startActivityForResult(intent,42);}catch(ActivityNotFoundException e){pendingCsv=null;Toast.makeText(this,"Không tìm thấy trình lưu tệp",Toast.LENGTH_SHORT).show();}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=42)return;String csv=pendingCsv;pendingCsv=null;if(result!=RESULT_OK||data==null||data.getData()==null||csv==null)return;try(java.io.OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new java.io.IOException();out.write(csv.getBytes(java.nio.charset.StandardCharsets.UTF_8));Toast.makeText(this,"Đã xuất CSV",Toast.LENGTH_SHORT).show();}catch(java.io.IOException|SecurityException e){Toast.makeText(this,"Không thể lưu báo cáo",Toast.LENGTH_SHORT).show();}}
    private void managedProtection(){android.app.admin.DevicePolicyManager dpm=(android.app.admin.DevicePolicyManager)getSystemService(DEVICE_POLICY_SERVICE);ComponentName admin=new ComponentName(this,StudyAdmin.class);if(!dpm.isDeviceOwnerApp(getPackageName())){new AlertDialog.Builder(this).setTitle("Chưa phải thiết bị được quản lý").setMessage("Chỉ dùng trên thiết bị riêng của trẻ do phụ huynh sở hữu và quản lý. Cần cấp Device Owner hợp lệ trước (xem README). Không tự khóa phần Cài đặt, không tự cấp quyền quản trị.").setPositiveButton("Đóng",null).show();return;}boolean on=dpm.isUninstallBlocked(admin,getPackageName());new AlertDialog.Builder(this).setTitle(on?"Tắt bảo vệ gỡ cài đặt?":"Bật bảo vệ gỡ cài đặt?").setMessage("Chỉ áp dụng cho StudyLock. Không ngăn tắt Trợ năng. Có thể tắt bảo vệ tại đây bằng PIN; gỡ quyền Device Owner cần quy trình riêng.").setNegativeButton("Hủy",null).setPositiveButton("Xác nhận",(d,w)->{if(!authorized)return;try{dpm.setUninstallBlocked(admin,getPackageName(),!on);Toast.makeText(this,!on?"Đã bật bảo vệ":"Đã tắt bảo vệ",Toast.LENGTH_SHORT).show();}catch(SecurityException e){Toast.makeText(this,"Không có quyền quản lý phù hợp",Toast.LENGTH_LONG).show();}}).show();}
    private void renderWindows(LinearLayout rows,List<int[]> windows){rows.removeAllViews();if(windows.isEmpty()){rows.addView(Ui.text(this,"Chưa có khung giờ tự do",14,Ui.MUTED,false));return;}for(int i=0;i<windows.size();i++){final int index=i;int[] w=windows.get(i);LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER_VERTICAL);Button edit=Ui.button(this,Rules.hhmm(w[0])+" – "+Rules.hhmm(w[1]),false);edit.setOnClickListener(v->editWindow(rows,windows,index));row.addView(edit,new LinearLayout.LayoutParams(0,-2,1));Button remove=Ui.button(this,"Xóa",false);remove.setOnClickListener(v->{windows.remove(index);renderWindows(rows,windows);});row.addView(remove);rows.addView(row);}}
    private void editWindow(LinearLayout rows,List<int[]> windows,int index){int[] initial=index<0?new int[]{480,510}:windows.get(index);new TimePickerDialog(this,(view,h,m)->{int start=h*60+m;new TimePickerDialog(this,(endView,eh,em)->{int end=eh*60+em;if(start==end){Toast.makeText(this,"Giờ bắt đầu và kết thúc phải khác nhau",Toast.LENGTH_LONG).show();return;}int[] w={start,end};if(index<0)windows.add(w);else windows.set(index,w);windows.sort(Comparator.comparingInt(x->x[0]));renderWindows(rows,windows);},initial[1]/60,initial[1]%60,true).show();},initial[0]/60,initial[0]%60,true).show();}
    private void changePin(){LinearLayout box=Ui.column(this);EditText a=new EditText(this),b=new EditText(this);for(EditText x:new EditText[]{a,b}){x.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);x.setSingleLine(true);x.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(12)});box.addView(x);}a.setHint("PIN mới (6–12 chữ số)");b.setHint("Nhập lại PIN mới");AlertDialog d=new AlertDialog.Builder(this).setTitle("Đổi mã PIN").setView(box).setNegativeButton("Hủy",null).setPositiveButton("Lưu",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{String pin=a.getText().toString();if(!pin.matches("[0-9]{6,12}")||!pin.equals(b.getText().toString())){b.setError("PIN không hợp lệ hoặc không khớp");return;}if(store.setPin(pin)){d.dismiss();Toast.makeText(this,"Đã đổi PIN",Toast.LENGTH_SHORT).show();}else b.setError("Không lưu được PIN");}));d.show();}
}
